/** Builds and test-signs the same v0 message as the browser, entirely offline. */
import {Buffer} from 'buffer';
import {Keypair,PublicKey} from '@solana/web3.js';
import {LOCAL_PROGRAM_ID} from '../client/guard.mjs';
import {officialSwapFixture} from './sdk-fixture.mjs';
import {buildVenueBuyInstructions,assembleBuyTransaction} from '../../src/live-chain.mjs';
import {planGuardedInstructions} from '../../src/guarded-trade.mjs';
let text='';for await(const chunk of process.stdin)text+=chunk;
const input=JSON.parse(text);
// This private test key is freshly generated by LiteSVM, passed through stdin only,
// and never written to an artifact. This tool must not be given a real wallet key.
const user=Keypair.fromSecretKey(Uint8Array.from(input.testUserSecret));
const {state,manifest,accounts,connection}=await officialSwapFixture(user.publicKey);
const market={mint:manifest.mint,venue:'PumpSwap',venueAddress:manifest.pool,tokenProgram:state.baseTokenProgram.toBase58(),slot:input.slot};
const capturedGlobal=accounts.get(manifest.accounts.amm_global_config);
const {PUMP_AMM_SDK}=await import('@pump-fun/pump-sdk/swap');
const all=PUMP_AMM_SDK.decodeGlobalConfig(capturedGlobal).buybackFeeRecipients;
const selected=all.findIndex(k=>k.equals(new PublicKey(manifest.buyback_fee_recipient)));
if(selected<0)throw Error('Captured recipient is not listed');
const previousRandom=Math.random;let built;
try{Math.random=()=> (selected+0.5)/all.length;built=await buildVenueBuyInstructions({connection,market,user:user.publicKey,input:1_000_000n,slippageBps:100});}finally{Math.random=previousRandom;}
const policyInfo=input.policyData!==null&&input.policyData!==undefined?{owner:new PublicKey(input.policyOwner??LOCAL_PROGRAM_ID),lamports:input.policyLamports??0,executable:false,data:Buffer.from(input.policyData,'base64')}:null;
const plan=await planGuardedInstructions({programId:LOCAL_PROGRAM_ID,market,wallet:user.publicKey,config:{capOn:true,quote:'SOL',cap:input.cap??'0.002',rollingOn:false,cooldownOn:false,accountOn:false},instructions:built.instructions,maxNativeDebit:BigInt(input.maxNativeDebit??'10000000'),snapshot:{context:{slot:input.slot},value:policyInfo}});
const tx=assembleBuyTransaction({user:user.publicKey,blockhash:input.blockhash,instructions:plan.instructions});
tx.sign([user]);
process.stdout.write(JSON.stringify({wire:Buffer.from(tx.serialize()).toString('base64'),wireBytes:tx.serialize().length,guard:plan.guard,minOut:built.minOut.toString(),expected:built.expected.toString(),version:tx.version}));
